// GUI theme: in the GUI (orthographic projection), shift neutral greys towards blue, keeping their brightness.
// Colored texels (icons, the health bar...) have some saturation and are left alone.
if (ProjMat[2][3] == 0.0) {
    float lum = dot(color.rgb, vec3(0.299, 0.587, 0.114));
    float saturation = max(max(color.r, color.g), color.b) - min(min(color.r, color.g), color.b);
    if (saturation < 0.06) {
        color.rgb = lum * vec3(0.78, 0.9, 1.25);
    }
}
fragColor = color * ColorModulator;
